\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Advocacy Color Palette ──
\definecolor{bgdark}{HTML}{1A1210}
\definecolor{primary}{HTML}{B22222}
\definecolor{secondary}{HTML}{E8731A}
\definecolor{accent}{HTML}{DAA520}
\definecolor{cardbg}{HTML}{2D1F16}
\definecolor{cardlight}{HTML}{3A2A1E}
\definecolor{warmwhite}{HTML}{FFF5E6}
\definecolor{mutedtext}{HTML}{BFA88F}
\definecolor{divider}{HTML}{5A3A2A}
\definecolor{ctaorange}{HTML}{D4641A}
\definecolor{statbg}{HTML}{382618}

\pagecolor{bgdark}
\color{warmwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=12, rows=24, spacing=4mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR — rows top to row3
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, colframe=bgdark, colupper=warmwhite,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={5pt}{0pt}{accent},
]{name=title, column=1, span=12, between=top and row4}{
  {\fontsize{88}{106}\selectfont\bfseries\color{accent} HUNGER DOESN'T WAIT}\\[20pt]
  {\fontsize{56}{68}\selectfont\color{warmwhite}\bfseries Together We Can End It}
}

% ══════════════════════════════════════════════════════════
% HERO STAT — 48 MILLION — rows 4 to 8
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=30pt, right=30pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=herostats, column=1, span=12, between=row4 and row9}{
  {\fontsize{160}{192}\selectfont\bfseries\color{secondary} 48 MILLION}\\[14pt]
  {\fontsize{46}{56}\selectfont\color{warmwhite} Americans face hunger every day}\\[18pt]
  {\fontsize{38}{46}\selectfont\color{mutedtext} Including }%
  {\fontsize{42}{50}\selectfont\bfseries\color{accent} 14 million children}%
  {\fontsize{38}{46}\selectfont\color{mutedtext} ~---~ in every state, every community}
}

% ══════════════════════════════════════════════════════════
% IMPACT SECTION HEADER
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=40pt, right=40pt, top=2pt, bottom=0pt,
  halign=center, valign=center,
]{name=impactheader, column=1, span=12, between=row9 and row10}{
  {\fontsize{44}{54}\selectfont\bfseries\color{warmwhite} OUR COLLECTIVE IMPACT}\\[4pt]
  {\fontsize{28}{36}\selectfont\color{mutedtext} The nation's largest hunger-relief network in action}
}

% ══════════════════════════════════════════════════════════
% IMPACT STATS — 4 stat cards — rows 10 to 13
% ══════════════════════════════════════════════════════════
% Stat 1: 5.7B Meals
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline north={5pt}{0pt}{secondary},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=stat1, column=1, span=3, between=row10 and row13}{
  {\fontsize{80}{96}\selectfont\bfseries\color{secondary} 5.7B}\\[8pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Meals}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Distributed}
}

% Stat 2: 4.3B Pounds
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline north={5pt}{0pt}{accent},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=stat2, column=4, span=3, between=row10 and row13}{
  {\fontsize{80}{96}\selectfont\bfseries\color{accent} 4.3B}\\[8pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Pounds of Food}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Rescued}
}

% Stat 3: 60,000+
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline north={5pt}{0pt}{primary!80!warmwhite},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=stat3, column=7, span=3, between=row10 and row13}{
  {\fontsize{72}{86}\selectfont\bfseries\color{primary!80!warmwhite} 60,000\kern-2pt\raisebox{10pt}{\fontsize{50}{60}\selectfont +}}\\[8pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Free Food}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Programs}
}

% Stat 4: 200+
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline north={5pt}{0pt}{secondary!70!accent},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=stat4, column=10, span=3, between=row10 and row13}{
  {\fontsize{80}{96}\selectfont\bfseries\color{secondary!70!accent} 200\kern-2pt\raisebox{10pt}{\fontsize{50}{60}\selectfont +}}\\[8pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Food Banks}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Nationwide}
}

% ══════════════════════════════════════════════════════════
% HOW WE UNITE — 4 pillars — rows 13 to 17
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=40pt, right=40pt, top=4pt, bottom=0pt,
  halign=center, valign=center,
]{name=uniteheader, column=1, span=12, between=row13 and row14}{
  {\fontsize{44}{54}\selectfont\bfseries\color{accent} HOW WE UNITE COMMUNITIES}
}

% Pillar 1 — Research-Driven
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline west={6pt}{0pt}{secondary},
  left=20pt, right=16pt, top=12pt, bottom=12pt,
  valign=center,
]{name=pillar1, column=1, span=3, between=row14 and row17}{
  {\fontsize{36}{44}\selectfont\bfseries\color{secondary} Research-Driven}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Listening to neighbors facing hunger and sharing their stories to shape real solutions}
}

% Pillar 2 — Local Wisdom
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline west={6pt}{0pt}{accent},
  left=20pt, right=16pt, top=12pt, bottom=12pt,
  valign=center,
]{name=pillar2, column=4, span=3, between=row14 and row17}{
  {\fontsize{36}{44}\selectfont\bfseries\color{accent} Local Wisdom}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Food bank leaders turn community knowledge into nationwide impact every day}
}

% Pillar 3 — Nationwide Scale
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline west={6pt}{0pt}{primary!80!warmwhite},
  left=20pt, right=16pt, top=12pt, bottom=12pt,
  valign=center,
]{name=pillar3, column=7, span=3, between=row14 and row17}{
  {\fontsize{36}{44}\selectfont\bfseries\color{primary!80!warmwhite} Nationwide Scale}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Moving food quickly and reliably to where it is needed most across all 50 states}
}

% Pillar 4 — Nutrition
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  borderline west={6pt}{0pt}{secondary!70!accent},
  left=20pt, right=16pt, top=12pt, bottom=12pt,
  valign=center,
]{name=pillar4, column=10, span=3, between=row14 and row17}{
  {\fontsize{36}{44}\selectfont\bfseries\color{secondary!70!accent} Nutrition First}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Making nutritious food accessible so everyone can lead fuller, healthier lives}
}

% ══════════════════════════════════════════════════════════
% $1 = 10 MEALS — Conversion Banner — rows 17 to 20
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=50pt, right=50pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
]{name=conversion, column=1, span=12, between=row17 and row20}{
  {\fontsize{110}{132}\selectfont\bfseries\color{warmwhite} \$1\, =\, 10 Meals}\\[14pt]
  {\fontsize{40}{48}\selectfont\color{warmwhite!95} Every dollar provides at least 10 meals to neighbors in need}\\[8pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite!80}\itshape Gifts are matched for a limited time --- double your impact today}
}

% ══════════════════════════════════════════════════════════
% TAKE ACTION — 4 CTAs — rows 20 to 23
% ══════════════════════════════════════════════════════════
% CTA 1: Donate
\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=4pt,
  borderline south={5pt}{0pt}{secondary},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=cta1, column=1, span=3, between=row20 and row23}{
  {\fontsize{48}{58}\selectfont\bfseries\color{secondary} DONATE}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Your gift moves fresh food to neighbors in need --- fast}
}

% CTA 2: Advocate
\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=4pt,
  borderline south={5pt}{0pt}{accent},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=cta2, column=4, span=3, between=row20 and row23}{
  {\fontsize{48}{58}\selectfont\bfseries\color{accent} ADVOCATE}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Urge lawmakers to support programs helping hungry neighbors}
}

% CTA 3: Fundraise
\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=4pt,
  borderline south={5pt}{0pt}{primary!80!warmwhite},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=cta3, column=7, span=3, between=row20 and row23}{
  {\fontsize{48}{58}\selectfont\bfseries\color{primary!80!warmwhite} FUNDRAISE}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Rally your community to come together and make a collective difference}
}

% CTA 4: Volunteer
\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=4pt,
  borderline south={5pt}{0pt}{secondary!70!accent},
  left=16pt, right=16pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=cta4, column=10, span=3, between=row20 and row23}{
  {\fontsize{48}{58}\selectfont\bfseries\color{secondary!70!accent} VOLUNTEER}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{warmwhite} Sort, pack, and distribute food --- many hands, including yours}
}

% ══════════════════════════════════════════════════════════
% FOOTER — rows 23 to bottom
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  borderline north={3pt}{0pt}{accent!60},
  left=50pt, right=50pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=footer, column=1, span=12, between=row23 and bottom}{
  {\fontsize{36}{44}\selectfont\color{warmwhite} When communities unite, an America without hunger is within reach.}\\[8pt]
  {\fontsize{30}{38}\selectfont\bfseries\color{accent} FeedingAmerica.org}
}

\end{tcbposter}
\end{document}
LATEXEOF
