\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{helvet}
\renewcommand{\familydefault}{\sfdefault}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Advocacy Color Palette ──
\definecolor{bgdark}{HTML}{1A1210}
\definecolor{bgmid}{HTML}{221812}
\definecolor{primary}{HTML}{C0392B}
\definecolor{secondary}{HTML}{E8731A}
\definecolor{accent}{HTML}{DAA520}
\definecolor{cardbg}{HTML}{2D1F16}
\definecolor{cardlight}{HTML}{3A2A1E}
\definecolor{warmwhite}{HTML}{FFF5E6}
\definecolor{mutedtext}{HTML}{C0A888}
\definecolor{divider}{HTML}{5A3A2A}

\pagecolor{bgdark}
\color{warmwhite}

\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=12, rows=30, spacing=3mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, colframe=bgdark, colupper=warmwhite,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=24pt, bottom=14pt,
  halign=center, valign=center,
  borderline south={6pt}{0pt}{accent},
]{name=title, column=1, span=12, between=top and row5}{
  {\fontsize{82}{98}\selectfont\bfseries\color{accent}%
  HUNGER\enskip DOESN'T\enskip WAIT}\\[24pt]
  {\fontsize{52}{62}\selectfont\bfseries\color{warmwhite}%
  Together\enskip We\enskip Can\enskip End\enskip It}
}

% ══════════════════════════════════════════════════════════
% HERO STAT — 48 MILLION
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgmid, boxrule=0pt, arc=0pt,
  left=40pt, right=40pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
]{name=herostats, column=1, span=12, between=row5 and row12}{
  {\fontsize{170}{204}\selectfont\bfseries\color{secondary}%
  48\enskip MILLION}\\[20pt]
  {\fontsize{46}{55}\selectfont\color{warmwhite}%
  Americans face hunger every day}\\[24pt]
  {\fontsize{38}{46}\selectfont\color{mutedtext}%
  Including\quad}%
  {\fontsize{42}{50}\selectfont\bfseries\color{accent}%
  14 million children}%
  {\fontsize{38}{46}\selectfont\color{mutedtext}%
  \quad---\quad in every state, every community}
}

% ══════════════════════════════════════════════════════════
% IMPACT HEADER
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=40pt, right=40pt, top=6pt, bottom=4pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{divider},
]{name=impactheader, column=1, span=12, between=row12 and row13}{
  {\fontsize{46}{55}\selectfont\bfseries\color{warmwhite}%
  OUR\enskip COLLECTIVE\enskip IMPACT}
}

% ══════════════════════════════════════════════════════════
% IMPACT STATS — 4 cards
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline north={5pt}{0pt}{secondary},
  left=16pt, right=16pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
]{name=stat1, column=1, span=3, between=row13 and row17}{
  {\fontsize{86}{103}\selectfont\bfseries\color{secondary} 5.7B}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Meals}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Distributed}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline north={5pt}{0pt}{accent},
  left=16pt, right=16pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
]{name=stat2, column=4, span=3, between=row13 and row17}{
  {\fontsize{86}{103}\selectfont\bfseries\color{accent} 4.3B}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Pounds of Food}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Rescued}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline north={5pt}{0pt}{primary!80!warmwhite},
  left=16pt, right=16pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
]{name=stat3, column=7, span=3, between=row13 and row17}{
  {\fontsize{76}{91}\selectfont\bfseries\color{primary!80!warmwhite} 60,000+}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Free Food}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Programs}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline north={5pt}{0pt}{secondary!70!accent},
  left=16pt, right=16pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
]{name=stat4, column=10, span=3, between=row13 and row17}{
  {\fontsize{86}{103}\selectfont\bfseries\color{secondary!70!accent} 200+}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Food Banks}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite} Nationwide}
}

% ══════════════════════════════════════════════════════════
% HOW WE UNITE
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
  left=40pt, right=40pt, top=6pt, bottom=4pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{divider},
]{name=uniteheader, column=1, span=12, between=row17 and row18}{
  {\fontsize{46}{55}\selectfont\bfseries\color{accent}%
  HOW\enskip WE\enskip UNITE\enskip COMMUNITIES}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline west={6pt}{0pt}{secondary},
  left=24pt, right=16pt, top=16pt, bottom=16pt,
  valign=center,
]{name=pillar1, column=1, span=3, between=row18 and row22}{
  {\fontsize{36}{44}\selectfont\bfseries\color{secondary} Research-Driven}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Listening to neighbors facing hunger and sharing their stories to shape real solutions}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline west={6pt}{0pt}{accent},
  left=24pt, right=16pt, top=16pt, bottom=16pt,
  valign=center,
]{name=pillar2, column=4, span=3, between=row18 and row22}{
  {\fontsize{36}{44}\selectfont\bfseries\color{accent} Local Wisdom}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Food bank leaders turn community knowledge into nationwide impact every single day}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline west={6pt}{0pt}{primary!80!warmwhite},
  left=24pt, right=16pt, top=16pt, bottom=16pt,
  valign=center,
]{name=pillar3, column=7, span=3, between=row18 and row22}{
  {\fontsize{36}{44}\selectfont\bfseries\color{primary!80!warmwhite} Nationwide Scale}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Moving food quickly and reliably to communities in need across all 50 states and Puerto Rico}
}

\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=6pt,
  borderline west={6pt}{0pt}{secondary!70!accent},
  left=24pt, right=16pt, top=16pt, bottom=16pt,
  valign=center,
]{name=pillar4, column=10, span=3, between=row18 and row22}{
  {\fontsize{36}{44}\selectfont\bfseries\color{secondary!70!accent} Nutrition First}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Making nutritious food accessible so everyone can lead fuller, healthier lives}
}

% ══════════════════════════════════════════════════════════
% $1 = 10 MEALS — Conversion Banner
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=60pt, right=60pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=conversion, column=1, span=12, between=row22 and row26}{
  {\fontsize{120}{144}\selectfont\bfseries\color{warmwhite}%
  \$1\enskip =\enskip 10\enskip Meals}\\[18pt]
  {\fontsize{40}{48}\selectfont\color{warmwhite!95}%
  Every dollar provides at least 10 meals to neighbors in need}\\[12pt]
  {\fontsize{34}{42}\selectfont\color{warmwhite!80}\itshape%
  Gifts are matched for a limited time --- double your impact today}
}

% ══════════════════════════════════════════════════════════
% TAKE ACTION — 4 CTAs
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=6pt,
  borderline south={6pt}{0pt}{secondary},
  left=16pt, right=16pt, top=18pt, bottom=18pt,
  halign=center, valign=center,
]{name=cta1, column=1, span=3, between=row26 and row29}{
  {\fontsize{48}{58}\selectfont\bfseries\color{secondary} DONATE}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Your gift moves fresh food\\to neighbors in need --- fast}
}

\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=6pt,
  borderline south={6pt}{0pt}{accent},
  left=16pt, right=16pt, top=18pt, bottom=18pt,
  halign=center, valign=center,
]{name=cta2, column=4, span=3, between=row26 and row29}{
  {\fontsize{48}{58}\selectfont\bfseries\color{accent} ADVOCATE}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Urge lawmakers to support\\hunger-relief programs}
}

\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=6pt,
  borderline south={6pt}{0pt}{primary!80!warmwhite},
  left=16pt, right=16pt, top=18pt, bottom=18pt,
  halign=center, valign=center,
]{name=cta3, column=7, span=3, between=row26 and row29}{
  {\fontsize{48}{58}\selectfont\bfseries\color{primary!80!warmwhite} FUNDRAISE}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Rally your community to make\\a collective difference}
}

\posterbox[
  enhanced, colback=cardlight, boxrule=0pt, arc=6pt,
  borderline south={6pt}{0pt}{secondary!70!accent},
  left=16pt, right=16pt, top=18pt, bottom=18pt,
  halign=center, valign=center,
]{name=cta4, column=10, span=3, between=row26 and row29}{
  {\fontsize{48}{58}\selectfont\bfseries\color{secondary!70!accent} VOLUNTEER}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{warmwhite} Sort, pack, and distribute\\food --- many hands needed}
}

% ══════════════════════════════════════════════════════════
% FOOTER
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, boxrule=0pt, arc=0pt,
